74:const MAX_LOG_CHARS = 8000;
75:
76:const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
77:
78:/** Append a timestamped line to a log tail, keeping it bounded. */
79:function appendLog(prev: string | null | undefined, line: string): string {
80:  const stamp = new Date().toISOString().slice(11, 19);
81:  const next = `${prev ?? ""}${prev ? "\n" : ""}[${stamp}] ${line}`;
82:  return next.length > MAX_LOG_CHARS ? next.slice(next.length - MAX_LOG_CHARS) : next;
83:}
