85:async function loadMigration(job: Job) {
86:  const payload = (job.payload ?? {}) as MigratePayload;
87:  if (!payload.migrationId) throw new Error("migrate job: missing migrationId");
88:  const migration = await db.migration.findUnique({ where: { id: payload.migrationId } });
89:  if (!migration) throw new Error(`Migration ${payload.migrationId} not found`);
90:  // Migration has no Prisma relation to Server (serverId is a plain FK) — resolve
91:  // the target server row separately. `dedicatedIp` is needed by the real engine
92:  // to compute the SSH connection target.
93:  const server = await db.server.findUnique({
94:    where: { id: migration.serverId },
95:    include: { dedicatedIp: true },
96:  });
97:  return { ...migration, server };
98:}
