100:/**
101: * Strip every source secret from a migration row. Called once the job finishes
102: * (success or failure) so a completed migration never keeps usable credentials.
103: */
104:async function clearSecrets(
105:  migrationId: string,
106:  items: MigrationItems,
107:  results?: MigrationStepResult[]
108:) {
109:  // Preserve every NON-secret field (so the wizard/summary keep working) while
110:  // stripping the only secret carried in items — each legacy DB's passEnc. The
111:  // source SSH password (sourcePasswordEnc column) is nulled separately.
112:  const scrubbed: MigrationItems = {
113:    ...items,
114:    databases: (items.databases ?? []).map((d) => ({
115:      engine: d.engine,
116:      name: d.name,
117:      user: d.user,
118:      // passEnc dropped entirely
119:    })),
120:    ...(results ? { results } : {}),

120:    ...(results ? { results } : {}),
121:  };
122:  await db.migration.update({
123:    where: { id: migrationId },
124:    data: { sourcePasswordEnc: null, items: scrubbed as any },
125:  });
126:}
