151:// ---- TLS inputs: resolved HERE, on the Nxeon side --------------------------
152:/**
153: * The three certificate inputs `runRealMigration` / `issueMigrationCertificates`
154: * declare and that this caller used to drop on the floor.
155: *
156: * Real incident: the engine shipped a complete three-rung TLS ladder
157: * (migrated certificate → DNS-01 wildcard via Cloudflare → HTTP-01 webroot) and
158: * this call site passed only `{migration, target, items, report}`. The
159: * consequences were invisible because every rung *degraded politely*:
160: *
161: *   - no `cloudflareToken`  ⇒ rung 3 could never fire, so every multi-tenant
162: *     app was told "Connect Cloudflare in Settings" even when the customer had
163: *     already completed the OAuth flow. A `*.domain` cert cannot be issued any
164: *     other way (HTTP-01 cannot validate a wildcard), so those tenants were
165: *     permanently stuck on a certificate warning.
166: *   - no `acmeEmail`        ⇒ every certificate registered
167: *     `--register-unsafely-without-email`, so Let's Encrypt has no address to
168: *     send the 20/7/1-day expiry warnings to. That failure is silent for 60 days
169: *     and then takes the site down.
170: *   - no `knownDomains`     ⇒ hostnames the customer registered WITH US were
171: *     excluded from the published set and from the certificate SANs.
172: *
173: * Everything is read from OUR database — never off the customer's box.
174: * Resolution never throws: a missing/expired Cloudflare connection simply drops
175: * the engine to a lower rung, exactly as it does for a customer who never
176: * connected, and that is reported honestly in the run log.
177: */
178:type MigrationTlsInputs = {
179:  cloudflareToken: string | null;
180:  acmeEmail: string | null;
181:  knownDomains: string[];
182:  /** One line for the run log, so the customer can see which rungs are available. */
183:  note: string;
184:};
185:
186:async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
187:  let cloudflareToken: string | null = null;
188:  let acmeEmail: string | null = null;
189:  const knownDomains: string[] = [];
190:  const notes: string[] = [];
191:
192:  try {
193:    const user = await db.user.findUnique({
194:      where: { id: userId },
195:      select: { id: true, email: true, cloudflareTokenEnc: true },
196:    });
197:    if (user) {
198:      // The account email is the ACME contact. This is what turns Let's
199:      // Encrypt's expiry warnings back on; without it a certificate that stops
200:      // renewing is only discovered by a visitor.
201:      acmeEmail = user.email ?? null;
202:      const resolved = await resolveCloudflareToken(user);
203:      if (resolved.token) {
204:        cloudflareToken = resolved.token;
205:        notes.push("your connected Cloudflare account is available, so wildcard certificates can be issued automatically (DNS-01)");
206:      } else {
207:        notes.push(
208:          "Cloudflare is not connected, so a wildcard certificate (needed when an app gives each tenant its own subdomain) cannot be issued automatically — connect it in Settings and we can finish that for you"
209:        );
210:      }
211:    }
212:  } catch (e) {
213:    // A DB hiccup here must never fail a migration — it only costs a rung.
214:    console.error("[migrate] could not resolve Cloudflare/ACME inputs", e);
215:    notes.push("we could not read your Cloudflare connection just now, so certificates were issued without it");
216:  }
217:
218:  try {
219:    const domains = await db.domain.findMany({
220:      where: { userId },
221:      select: { name: true },
222:      orderBy: { name: "asc" },
223:      take: 50,
224:    });
225:    for (const d of domains) if (d.name) knownDomains.push(d.name);
226:  } catch (e) {
227:    console.error("[migrate] could not load registered domains", e);
228:  }
229:
230:  return { cloudflareToken, acmeEmail, knownDomains, note: notes.join("; ") };
231:}
