331:export async function runMigration(job: Job): Promise<void> {
332:  const migration = await loadMigration(job);
333:  const items = (migration.items ?? {}) as MigrationItems;
334:  const paths = items.paths ?? [];
335:  const target = migration.server;
336:  const targetName = target ? target.label || target.hostname : "your server";
337:
338:  // The post-cutover certificate pass shares this handler (and therefore the
339:  // already-registered MIGRATE JobType) but is NOT a migration: it copies
340:  // nothing and must never fall through into the transfer below.

340:  // nothing and must never fall through into the transfer below.
341:  if (((job.payload ?? {}) as MigratePayload).phase === "tls") {
342:    try {
343:      await runPostCutoverTls(migration, items);
344:    } catch (e) {
345:      console.error(`[migrate] post-cutover TLS for ${migration.id} failed:`, e);
346:      // Swallowed on purpose: a failed certificate retry must not mark the
347:      // customer's finished migration as failed, and must not make the job loop
348:      // retry a phase that will keep failing for the same reason.
349:    }
350:    return;
351:  }
352:
353:  // Fresh start (also lets a retried job re-enter cleanly).
354:  let log = appendLog(null, `Starting migration from ${migration.sourceUser}@${migration.sourceHost}:${migration.sourcePort} → ${targetName}`);
355:  await db.migration.update({
356:    where: { id: migration.id },
357:    data: { status: "RUNNING", progress: 5, step: "Starting", log, lastError: null, finishedAt: null },
358:  });
359:
360:  // Shared progress reporter: threads the bounded log tail through each update so
361:  // both the real engine and the simulation write to the same Migration row.
362:  const reportStep = async (progress: number, step: string, line: string) => {
363:    log = await report(migration.id, progress, step, line, log);
364:  };
365:
366:  try {
367:    if (REAL_MIGRATION) {
368:      // ---- REAL lift-and-shift (hardened; opt-in via ENABLE_REAL_MIGRATION) --
369:      // Resolve the TLS inputs BEFORE the engine starts. These three arguments
370:      // are what make the certificate ladder reachable at all — see
371:      // resolveTlsInputs for the failure each dropped argument caused.
372:      const tls = await resolveTlsInputs(migration.userId);
373:      if (tls.note) await reportStep(5, "Starting", `HTTPS: ${tls.note}.`);
374:
375:      const summary = await runRealMigration({
376:        migration: {
377:          id: migration.id,
378:          sourceHost: migration.sourceHost,
379:          sourcePort: migration.sourcePort,
380:          sourceUser: migration.sourceUser,
381:          sourcePasswordEnc: migration.sourcePasswordEnc,
382:        },
383:        target: target as any,
384:        items,
385:        report: reportStep,
386:        // Rung 3 of the certificate ladder: a wildcard (`*.domain`) can ONLY be
387:        // issued with a DNS-01 challenge, so a multi-tenant app is stuck on a
388:        // certificate warning without this token.
389:        cloudflareToken: tls.cloudflareToken,
390:        // Without this every cert is `--register-unsafely-without-email` and
391:        // Let's Encrypt has nobody to warn before it expires.
392:        acmeEmail: tls.acmeEmail,
393:        // Hostnames the customer registered with us, folded into the published
394:        // set and the certificate SANs when they belong to a served site.
395:        knownDomains: tls.knownDomains,
396:      });
397:
398:      // The engine returns an HONEST outcome. A run that executed every step but
399:      // left a source domain dark — or a migrated unit crash-looping — is NOT a
400:      // success, and must never be written back as one.
401:      //
402:      // This line is why the 2026-07-25 migration reported "Completed" while the
403:      // customer's site served a certificate warning and then Apache's default
404:      // page: the status was hardcoded, so no amount of verification downstream
405:      // could change what the customer was told. `COMPLETED_WITH_ISSUES` is
406:      // terminal (MigrationWizard treats it as an end state) but visibly distinct.
407:      const clean = summary.outcome === "COMPLETED";
408:      const unserved = summary.unservedDomains ?? [];
409:      await db.migration.update({
410:        where: { id: migration.id },
411:        data: {
412:          status: clean ? "DONE" : "COMPLETED_WITH_ISSUES",
413:          progress: 100,
414:          step: clean ? "Completed" : "Finished — some sites need attention",
415:          finishedAt: new Date(),
416:        },
417:      });
418:      // Persist the honest step-by-step summary (secret-free) into items.results.
419:      await clearSecrets(migration.id, items, summary.results);
420:
421:      const workDir = migrationWorkDir(migration.id);
422:      const running = summary.verifiedRunning.length;
423:      const manual = summary.needsAttention.length;
424:      const tail =
425:        `Any DB dumps that couldn't import were kept under ${workDir}/dumps. ` +
