2045:/**
2046: * HTTP-probe one URL from the target itself and return its status code
2047: * ("000" = nothing answered at all).
2048: *
2049: * `resolve` pins the hostname to 127.0.0.1 with `curl --resolve`, which sends the
2050: * real Host header AND the real TLS SNI while never leaving the box. That is what
2051: * makes this a genuine test of "will the customer's domain serve once DNS points
2052: * here" — a plain port check proves only that something is listening, which is
2053: * exactly how a migration can report success while the site returns 502 or the
2054: * stock welcome page. `-k` because at probe time the name still resolves
2055: * elsewhere; we are testing that the vhost matches and answers, not the chain.
2056: */
2057:async function httpProbe(
2058:  conn: Client,
2059:  url: string,
2060:  resolve?: { domain: string; port: number }
2061:): Promise<{ code: string; body: string }> {
2062:  const res = resolve ? `--resolve ${resolve.domain}:${resolve.port}:127.0.0.1 ` : "";
2063:  // The BODY is fetched as well as the status, because a status code alone
2064:  // cannot tell a real site from the stock Apache/nginx default page — see
2065:  // defaultPageReason. It lands in a `mktemp` file rather than a fixed /tmp
2066:  // name: on a migrated multi-user box a predictable path under /tmp is a
2067:  // symlink-overwrite waiting to happen, and this engine never takes a
2068:  // destructive risk with the customer's files.
2069:  const r = await sh(
2070:    conn,
2071:    `f=$(mktemp 2>/dev/null || echo /dev/null); ` +
2072:      `c=$(curl -sS -k --max-time 12 ${res}-o "$f" -w '%{http_code}' ${url} 2>/dev/null); ` +
2073:      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 4096 "$f" 2>/dev/null; ` +
2074:      `[ "$f" = /dev/null ] || rm -f "$f"`,
2075:    SETUP_TIMEOUT_MS
2076:  );
2077:  const out = String(r.stdout ?? "");
2078:  const m = /NXCODE:(\d{3})/.exec(out);
2079:  const nl = out.indexOf("\n");
2080:  return { code: m ? m[1] : "000", body: probeBody(nl < 0 ? "" : out.slice(nl + 1)) };
2081:}
2082:
2083:/** Status-code-only probe (unchanged contract) — now sharing one code path. */
2084:async function httpCode(conn: Client, url: string, resolve?: { domain: string; port: number }): Promise<string> {
2085:  return (await httpProbe(conn, url, resolve)).code;
2086:}
2087:
2088:/**
2089: * Bound a response body for pattern-matching. Deliberately NOT `clean()`:
2090: * `clean` strips ALL control characters including newlines, which would glue
2091: * "Apache2 Debian Default\nPage" into "Apache2 Debian DefaultPage" and make the
2092: * default-page markers unmatchable. Newline/tab/CR survive; everything else
2093: * becomes a space.
2094: */
2095:export function probeBody(raw: string, max = 4096): string {
2096:  // eslint-disable-next-line no-control-regex
2097:  return String(raw ?? "").replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ").slice(0, max);
2098:}
2099:
2100:/**
2101: * A response body shorter than this (after trimming) is not a website. A real
2102: * page — even a JavaScript app whose HTML is just a mount point — is hundreds of
2103: * bytes; a truly empty 200 is what a misrouted vhost or an empty document root
2104: * returns. Deliberately measured on the RAW body, not on stripped-tag "visible
2105: * text": a React/Next shell has almost no visible text and must NOT be flagged.
2106: */
2107:export const NEAR_EMPTY_BODY_BYTES = 64;
2108:
2109:/**
2110: * The stock pages a freshly-installed web server serves when NOTHING has claimed
2111: * the request. Every one of these answers 200, which is why the old
2112: * "make a real request to each domain" check passed for a dead site.
2113: *
2114: * Real incident, 2026-07-25: the run reported the customer's main site as
2115: * serving. The browser showed a certificate warning and then the Apache2 Debian
2116: * Default Page — apache2 had been re-enabled from the source and was answering
2117: * on a port our generated nginx config was supposed to own. A 200 from the
2118: * distribution's placeholder is a FAILED migration, not a successful one.
2119: */
2120:export const DEFAULT_PAGE_MARKERS: { re: RegExp; what: string }[] = [
2121:  { re: /Apache2\s+Debian\s+Default\s+Page/i, what: "the Apache2 Debian default page" },
2122:  { re: /Apache2\s+Ubuntu\s+Default\s+Page/i, what: "the Apache2 Ubuntu default page" },
2123:  { re: /Apache\s+HTTP\s+Server\s+Test\s+Page/i, what: "the stock Apache test page" },
2124:  // The classic /var/www/html/index.html: `<html><body><h1>It works!</h1></body></html>`.
2125:  // Anchored on the heading so a real site that merely contains the words
2126:  // "it works!" in its copy is never mistaken for a placeholder.
2127:  { re: /<h1>\s*It\s+works!\s*<\/h1>/i, what: `Apache's stock "It works!" page` },
2128:  { re: /Welcome\s+to\s+nginx!/i, what: `nginx's stock "Welcome to nginx!" page` },
2129:];
2130:
2131:/**
2132: * Why this response is a placeholder rather than the customer's site, or "" when
2133: * it looks like real content. Content is only judged on a 2xx: a 301 to HTTPS or
2134: * a 401/404 legitimately has a tiny (or empty) body and the status alone already
2135: * proves the vhost matched.
2136: */
2137:export function defaultPageReason(code: string, body: string): string {
2138:  if (!/^2\d\d$/.test(code)) return "";
2139:  for (const m of DEFAULT_PAGE_MARKERS) {
2140:    if (m.re.test(body)) return `it answered ${code} with ${m.what}, not your site`;
2141:  }
2142:  const t = body.trim();
2143:  // A short JSON/XML body is an API answering correctly, not an empty site — a
2144:  // vhost that legitimately returns `{"ok":true}` must never be called dark.
2145:  const structured = t.startsWith("{") || t.startsWith("[") || t.startsWith("<?xml");
2146:  if (!structured && t.length < NEAR_EMPTY_BODY_BYTES) {
2147:    return `it answered ${code} with an empty page (${t.length} bytes) — whatever should be behind this name is not there`;
2148:  }
2149:  return "";
2150:}
