2152:/**
2153: * The hostnames on the certificate this server actually presents for `domain`,
2154: * read with SNI so it is the same certificate a browser would be shown.
2155: * `null` means we could not determine it (no openssl, or nothing on 443) — an
2156: * unknown is never treated as a failure.
2157: *
2158: * Real incident, 2026-07-25: studionexis.com was served nexis.revsports.ca's
2159: * certificate, so every visitor got ERR_CERT_COMMON_NAME_INVALID before they
2160: * ever reached the site — and the run reported that domain as serving, because
2161: * the probe used `-k` and only looked at the status code.
2162: */
2163:async function servedCertNames(conn: Client, domain: string): Promise<string[] | null> {
2164:  if (!DOMAIN_RE.test(domain)) return null;
2165:  const r = await sh(
2166:    conn,
2167:    `T=$(command -v timeout >/dev/null 2>&1 && echo 'timeout 8'); ` +
2168:      `command -v openssl >/dev/null 2>&1 || exit 3; ` +
2169:      `$T openssl s_client -connect 127.0.0.1:443 -servername ${domain} </dev/null 2>/dev/null ` +
2170:      `| openssl x509 -noout -subject -ext subjectAltName 2>/dev/null`,
2171:    SETUP_TIMEOUT_MS
2172:  );
2173:  const out = probeBody(r.stdout, 4096);
2174:  if (!out.trim()) return null;
2175:  const names: string[] = [];
2176:  // `subject=CN = example.com`, `subject= /C=US/CN=example.com`, `CN=example.com`.
2177:  const cn = /CN\s*=\s*([^,/\r\n]+)/.exec(out);
2178:  if (cn) names.push(cn[1].trim());
2179:  for (const m of out.matchAll(/DNS:\s*([^,\s]+)/g)) names.push(m[1].trim());
2180:  const uniq = [...new Set(names.map((n) => n.toLowerCase().replace(/\.$/, "")).filter(Boolean))].slice(0, 40);
2181:  return uniq.length ? uniq : null;
2182:}
2183:
2184:/** Does a certificate carrying `certNames` cover `domain`? (`*.x` = ONE label.) */
2185:export function certCoversName(certNames: string[], domain: string): boolean {
2186:  const d = domain.toLowerCase().replace(/\.$/, "");
2187:  for (const n of certNames) {
2188:    if (n === d) return true;
2189:    if (n.startsWith("*.")) {
2190:      const base = n.slice(2);
2191:      const dot = d.indexOf(".");
2192:      if (base && dot > 0 && d.slice(dot + 1) === base) return true;
2193:    }
2194:  }
2195:  return false;
2196:}
