5100:    // ---- 12b. DOES THE SITE ACTUALLY SERVE? -------------------------------
5101:    // A listening port proves almost nothing: a real migration had the app up on
5102:    // 127.0.0.1:3720, the port open, and every request answered by the stock
5103:    // "Welcome to nginx" page — and a copied catch-all vhost happily answered 502
5104:    // for everything. So we make a REAL request for each hostname, with
5105:    // `curl --resolve` pinning it to this machine so the Host header and TLS SNI
5106:    // are the customer's actual domain. Anything 1xx–4xx means the vhost matched
5107:    // and something answered; 000 (nothing there) or 5xx does not.
5108:    //
5109:    // That was still not enough. On 2026-07-25 this check PASSED for a domain
5110:    // that was answering 200 with the Apache2 Debian Default Page, and for a
5111:    // domain that was being served a certificate belonging to a different site.
5112:    // So a 1xx–4xx is now necessary but not sufficient, and there are three more
5113:    // ways to fail:
5114:    //   - the body is a distribution placeholder or effectively empty
5115:    //     (defaultPageReason),
5116:    //   - the certificate this server presents for the name does not cover it
5117:    //     (servedCertNames — a browser shows a full-page security warning before
5118:    //     the visitor ever reaches the site),
5119:    //   - the name is simply not probed at all, because we never published it.
5120:    //
5121:    // And the LIST is now every hostname the SOURCE served, not the list we
5122:    // generated a config for. See the note on `sourceDomains`.
5123:    const siteProbes: { domain: string; http: string; https: string; serving: boolean; reason?: string }[] = [];
5124:    const publishedNames = [...new Set(servedSites.flatMap((s) => s.names))];
5125:    // Published names first (so the most important ones are inside the cap),
5126:    // then everything else the old server answered on.
5127:    const probeNames = [...new Set([...publishedNames, ...sourceDomains])].slice(0, 24);
5128:    const unprobed = [...new Set([...publishedNames, ...sourceDomains])].slice(24);
5129:    // Is anything at all listening on 443 here? Without that, https:// simply
5130:    // refuses the connection and there is no certificate to mismatch.
5131:    const tlsListening = await shOk(conn, `(ss -lnt 2>/dev/null || netstat -lnt 2>/dev/null) | grep -q ':443 '`);
5132:    if (probeNames.length) {
5133:      await report(
5134:        96,
5135:        "Verifying…",
5136:        `Making a real request to each of your ${probeNames.length} domain(s) to confirm the site actually answers — and checking what it answers WITH.`
5137:      );
5138:      for (const d of probeNames) {
5139:        const httpRes = await httpProbe(conn, `http://${d}/`, { domain: d, port: 80 });
5140:        const hasCert = await certExists(conn, d);
5141:        const httpsRes =
5142:          hasCert || tlsSecured.includes(d)
5143:            ? await httpProbe(conn, `https://${d}/`, { domain: d, port: 443 })
5144:            : { code: "", body: "" };
5145:        // With TLS present the HTTP block is a 301 to HTTPS, so HTTPS is the
5146:        // authoritative answer; without it, HTTP is.
5147:        const auth = httpsRes.code ? httpsRes : httpRes;
5148:        let serving = isServing(auth.code);
5149:        let reason = serving ? "" : auth.code === "000" ? "nothing answered at all" : `it answered ${auth.code}`;
5150:
5151:        // (i) A 200 from a distribution placeholder is a dead site.
5152:        if (serving) {
5153:          const placeholder = defaultPageReason(auth.code, auth.body);
5154:          if (placeholder) {
5155:            serving = false;
5156:            reason = placeholder;
5157:          }
5158:        }
5159:
5160:        // (ii) The certificate a browser would actually be shown. Checked
5161:        // whenever anything is listening on 443 — INCLUDING when we hold no
5162:        // certificate for this name, because that is precisely the case where
5163:        // another site's certificate gets served and the visitor is stopped by a
5164:        // security warning (studionexis.com was served nexis.revsports.ca's).
5165:        //
5166:        // Skipped when a CONTAINER owns 443: there the proxy issues its own
5167:        // certificates after DNS moves, so its placeholder self-signed cert
5168:        // today says nothing about tomorrow, and the HTTPS summary entry already
5169:        // explains that. The host is not the authority in that layout.
5170:        if (serving && tlsListening && webKind !== "container") {
5171:          const certNames = await servedCertNames(conn, d);
5172:          if (certNames && !certCoversName(certNames, d)) {
5173:            serving = false;
5174:            reason =
5175:              `this server answers https://${d}/ with a certificate issued for ${certNames.slice(0, 3).join(", ")}, which does not cover ${d} — ` +
5176:              `every visitor gets a full-page browser security warning before they reach the site`;
5177:          }
5178:        }
5179:
5180:        siteProbes.push({ domain: d, http: httpRes.code, https: httpsRes.code, serving, reason });
5181:      }
5182:      const good = siteProbes.filter((p) => p.serving);
5183:      const bad = siteProbes.filter((p) => !p.serving);
5184:      for (const p of good) {
5185:        push({
5186:          step: `Site ${p.domain}`,
5187:          status: "running",
5188:          detail: p.https
5189:            ? `serving over HTTPS (HTTP ${p.http} → HTTPS ${p.https}) — point ${p.domain} at this server and it works`
5190:            : `serving over HTTP (${p.http}) — no certificate yet, so visitors get a browser warning on https:// until one is issued`,
5191:        });
5192:      }
5193:      for (const p of bad) {
5194:        push({
5195:          step: `Site ${p.domain} is NOT serving`,
5196:          status: "failed",
5197:          detail:
5198:            p.http === "000" && !p.https
5199:              ? `nothing answered for ${p.domain} on this server — the web server is not serving this name yet, so pointing DNS here would show an error`
5200:              : `${p.reason || `${p.domain} answered ${p.https || p.http}`} — the old server answered on this name, so it is not migrated until this one does too. Check \`docker logs\` / \`systemctl status\` for the app behind it, then reload the web server`,
5201:        });
5202:        // Only if we do not already hold a better-targeted reason for this name
5203:        // (the "could not publish" entry above knows exactly what was missing).
5204:        if (!blockers.some((b) => b.domain === p.domain)) {
5205:          blockers.push({
5206:            domain: p.domain,
5207:            why: p.reason || `it answered ${p.https || p.http} on the new server`,
5208:            fix: `make ${p.domain} serve here (start the app behind it, add or fix its vhost, and issue a certificate that covers ${p.domain}), then re-run the check`,
5209:          });
5210:        }
5211:      }
5212:      await report(
5213:        96,
5214:        "Verifying…",
5215:        `  serving: ${good.map((p) => p.domain).join(", ") || "none"}${bad.length ? `; NOT serving: ${bad.map((p) => p.domain).join(", ")}` : ""}.`
5216:      );
5217:      if (unprobed.length) {
5218:        push({
5219:          step: `${unprobed.length} more domain(s) were not checked`,
5220:          status: "copied",
5221:          detail: `${unprobed.slice(0, 8).join(", ")}${unprobed.length > 8 ? " …" : ""} — the old server also answered on these, but only the first ${probeNames.length} were probed. Check them by hand before moving DNS`,
5222:        });
5223:      }
5224:    }
5225:    // Independent of the per-domain probes above (which now also run in the
5226:    // containerised layout, because the source's domains have to answer there
5227:    // too): does the proxy container itself answer on port 80 at all?
5228:    if (webKind === "container") {
5229:      const code = await httpCode(conn, `http://127.0.0.1/`);
5230:      push({
5231:        step: "Site (containerised proxy)",
5232:        status: isServing(code) ? "running" : "failed",
5233:        detail: isServing(code)
5234:          ? `your proxy container answers on port 80 (HTTP ${code}) — point your DNS here and it serves`
5235:          : "nothing answered on port 80 — start your reverse-proxy container and check `docker logs`, or your domain will not resolve to anything",
5236:      });
5237:    }
5238:
5239:    // ---- 13. Final honest summary ----------------------------------------
5240:    // THE SCORE. Denominator = every hostname the SOURCE served (sourceDomains),
5241:    // NOT the set we generated a config for. When the live inventory could not
5242:    // run we have no honest denominator and fall back to the probed set, saying
5243:    // so rather than quietly scoring ourselves against our own homework.
5244:    // judgeMigrationOutcome() is a pure function over exactly these four inputs,
5245:    // living next to the probe helpers, so `npm test` can assert the scoring rule
5246:    // directly. Before that extraction the rule existed only inline here, which
5247:    // is why "the success metric could not fail" survived to production.
5248:    const score = judgeMigrationOutcome({ sourceDomains, probeNames, siteProbes, unitBlockers });
5249:    const { scoredAgainst, unservedDomains, outcomeReasons, outcome } = score;
5250:
5251:    // The structured flag the UI keys off. worker/migrate.ts writes
5252:    // Migration.status = "DONE" unconditionally and persists ONLY
5253:    // summary.results into Migration.items.results — so the outcome is put at
5254:    // the TOP of results as a first-class line with a `failed` status, which is
5255:    // what actually reaches the customer's screen. `results.unshift` rather than
5256:    // push(): this line SUMMARISES the other entries, so duplicating it into
5257:    // needsAttention would just repeat every reason twice.
5258:    results.unshift({
5259:      step: outcome === "COMPLETED" ? "Migration outcome: COMPLETED" : "Migration outcome: COMPLETED_WITH_ISSUES",
5260:      status: outcome === "COMPLETED" ? "running" : "failed",
5261:      detail:
5262:        outcome !== "COMPLETED"
5263:          ? `this migration finished but is NOT done: ${outcomeReasons.join("; ")}. The individual entries below name each one with the command that fixes it.`
5264:          : scoredAgainst.length
5265:            ? `all ${scoredAgainst.length} domain(s) the old server answered on are serving on this server, and every migrated service is running`
5266:            : "everything selected was migrated and verified; the old server did not serve any websites, so there was nothing to publish",
5267:    });
5268:
5269:    await report(
5270:      97,
5271:      "Finalising…",
5272:      `Migrated & running (verified): ${verifiedRunning.length}. Copied — may need a manual step: ${needsAttention.length}.` +
5273:        (scoredAgainst.length
5274:          ? ` Sites actually serving: ${score.servingCount}/${scoredAgainst.length} of the domains the old server served.`
5275:          : "")
5276:    );
5277:    if (unservedDomains.length) {
5278:      await report(
5279:        97,
5280:        "Finalising…",
5281:        `NOT serving on the new server: ${unservedDomains.slice(0, 12).join(", ")}${unservedDomains.length > 12 ? ` and ${unservedDomains.length - 12} more` : ""} — do not move DNS for ${unservedDomains.length === 1 ? "this name" : "these names"} yet.`
5282:      );
5283:    }
5284:    if (unitBlockers.length) {
5285:      await report(
5286:        97,
5287:        "Finalising…",
5288:        `Services that are not running: ${unitBlockers.slice(0, 12).map((b) => b.domain).join(", ")}${unitBlockers.length > 12 ? " …" : ""} — each is listed in the summary with its actual error.`
5289:      );
5290:    }
5291:    if (tlsPending.length) {
5292:      await report(97, "Finalising…", `HTTPS still to finish: ${tlsPending.slice(0, 4).map((p) => p.domain).join(", ")}${tlsPending.length > 4 ? " …" : ""}`);
5293:    }
5294:    if (needsAttention.length) {
5295:      await report(98, "Finalising…", `Needs a manual step: ${needsAttention.slice(0, 8).join(" | ")}${needsAttention.length > 8 ? " …" : ""}`);
5296:    }
5297:    await report(
5298:      98,
5299:      "Finalising…",
5300:      outcome === "COMPLETED"
5301:        ? "Outcome: COMPLETED — every domain the old server served is serving here."
5302:        : `Outcome: COMPLETED_WITH_ISSUES — ${outcomeReasons.join("; ")}.`
5303:    );
5304:
5305:    return {
5306:      results,
5307:      verifiedRunning,
5308:      needsAttention,
5309:      tlsSecured,
5310:      tlsPending,
5311:      siteProbes,
5312:      sourceDomains: scoredAgainst,
5313:      unservedDomains,
5314:      blockers: [...blockers, ...unitBlockers],
5315:      outcome,
5316:      outcomeReasons,
5317:    };
5318:  } finally {
5319:    // Scrub every secret-bearing artefact from the target, always:
5320:    //   - the source SSH password file,
5321:    //   - the per-container env files (application secrets),
5322:    //   - the MySQL account SQL (password hashes),
5323:    //   - any Cloudflare DNS-01 credentials file.
5324:    // DB dumps under ${work}/dumps are intentionally kept so a failed import can
5325:    // be retried by hand; they hold data, not credentials.
5326:    await execRemote(conn, `shred -u ${passFile} 2>/dev/null || rm -f ${passFile}`, SETUP_TIMEOUT_MS).catch(() => {});
5327:    await execRemote(
5328:      conn,
5329:      `find ${work}/env -type f -exec shred -u {} \\; 2>/dev/null; rm -rf ${work}/env; ` +
5330:        `shred -u ${work}/dumps/mysql-users.sql ${work}/dumps/mysql-users.err ${work}/cf-dns.ini 2>/dev/null; ` +
5331:        `rm -f ${work}/dumps/mysql-users.sql ${work}/dumps/mysql-users.err ${work}/cf-dns.ini; true`,
5332:      SETUP_TIMEOUT_MS
5333:    ).catch(() => {});
5334:    try {
5335:      conn.end();
5336:    } catch {
5337:      /* best-effort */
5338:    }
5339:  }
5340:}
