256:// ---- Strict allowlist validators (throw/reject on any violation) ----------
257:// Charsets below are deliberately shell-inert: no quotes, spaces, metachars or
258:// newlines. Validated values are therefore safe to interpolate into a command.
259:const HOSTNAME_RE = /^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$/;
260:const IPV4_RE = /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;
261:const IPV6_RE = /^[0-9A-Fa-f:]{2,45}$/;
262:const USER_RE = /^[a-z_][a-z0-9_-]{0,31}$/;
263:const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/; // absolute path, safe charset
264:// Docker volume name (docker's own charset) and systemd unit name — shell-inert.
265:const VOLNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
266:const SVCNAME_RE = /^[A-Za-z0-9@][A-Za-z0-9@._-]{0,127}$/;
267:// Database identifier (schema name) — shell-inert (no metachars, quotes or spaces).
268:// MUST match DBNAME_RE in worker/migrate-detect.ts. Every DB name returned by the
269:// source's `SHOW DATABASES` is validated against this (reject, never sanitize)
270:// before it is interpolated into a mysqldump command.
271:const IDENT_RE = /^[A-Za-z0-9_]{1,64}$/;
272:// ---- Allowlists for everything the new phases interpolate -----------------
273:// Every charset below is shell-inert: no quote, space, newline, `$`, backtick,
274:// `;`, `|`, `&`, `<`, `>`, `(`, `)`, `*`, `?`, `~` or backslash can appear. A
275:// value that passes is therefore safe to place in a command; a value that fails
276:// is REJECTED (never sanitized) and the step falls back to logging it.
277://
278:// Docker image reference — `repo`, `ns/repo:tag`, `registry.io:5000/ns/repo@sha256:…`.
279:// MUST match IMAGEREF_RE in worker/migrate-detect.ts.
280:const IMAGEREF_RE = /^[A-Za-z0-9][A-Za-z0-9._:@/-]{0,254}$/;
281:// Docker container / network name (docker's own charset).
282:const CONTNAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/;
283:// A DNS hostname we are willing to write into a generated vhost or a curl Host
284:// header. MUST match DOMAIN_RE in worker/migrate-detect.ts.
285:const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/;
286:// MySQL account parts. `%` (the wildcard host) and `-`/`.`/`_` are all inert.
287:const MYSQL_USER_RE = /^[A-Za-z0-9_.-]{1,32}$/;
288:const MYSQL_HOST_RE = /^[A-Za-z0-9_.%-]{1,64}$/;
289:// Kernel block-device leaf name: sdb, vdb, nvme1n1, xvdf.
290:const BLOCKDEV_RE = /^[a-z][a-z0-9]{1,31}$/;
291:const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
292:// A Linux capability as `docker inspect` reports it (CAP_NET_ADMIN / NET_ADMIN).
293:const CAP_RE = /^(CAP_)?[A-Z][A-Z0-9_]{1,31}$/;
294:// `--user` value: name, uid, name:group or uid:gid.
295:const RUNUSER_RE = /^[A-Za-z0-9_][A-Za-z0-9_.:-]{0,64}$/;
296:
297:// Docker restart policies we will reproduce verbatim. Anything else is refused.
298:const RESTART_POLICIES = new Set(["no", "always", "unless-stopped", "on-failure"]);
299:// Docker's own built-in networks — these need no `docker network create`.
300:const BUILTIN_NETWORKS = new Set(["bridge", "host", "none", "default"]);
301:// MySQL's own plumbing accounts. Migrating these would overwrite the NEW
302:// server's root/maintenance logins and lock us out of our own box, so they are
303:// never touched; only real application accounts are reproduced.
304:const MYSQL_SYSTEM_USERS = new Set([
305:  "root", "mysql.sys", "mysql.session", "mysql.infoschema", "mariadb.sys",
306:  "debian-sys-maint", "healthchecker", "sys_maint", "",
307:]);
308:// Login shells we are willing to set on a recreated system user. Anything else
309:// falls back to nologin (the account still exists so file ownership resolves).
310:const LOGIN_SHELLS = new Set([
311:  "/bin/sh", "/bin/bash", "/bin/dash", "/bin/zsh", "/usr/bin/zsh", "/usr/bin/bash",
312:  "/usr/bin/fish", "/bin/false", "/usr/bin/false", "/sbin/nologin", "/usr/sbin/nologin",
313:  "/usr/bin/nologin",
314:]);
315:const NOLOGIN = "/usr/sbin/nologin";
316:// Image names that mean "this container IS the reverse proxy" — if one of these
317:// publishes :80/:443 the host web server must stay out of its way.
318:const PROXY_IMAGE_RE = /(^|\/)(traefik|caddy|nginx|haproxy|envoyproxy\/envoy|jwilder\/nginx-proxy|nginxproxy\/nginx-proxy|jc21\/nginx-proxy-manager)(:|$)/i;
