320:// Top-level system locations we refuse to overwrite on the target even if a
321:// (validated) path points at one — a lift-and-shift must never clobber the new
322:// server's own OS. Docker volumes/state are handled by their dedicated steps.
323:const UNSAFE_PREFIXES = [
324:  "/bin", "/sbin", "/usr", "/lib", "/lib64", "/etc/systemd", "/proc", "/sys",
325:  "/dev", "/run", "/boot", "/var/lib/docker",
326:];
327:const UNSAFE_EXACT = new Set(["/", "/etc", "/var", "/var/lib", "/usr", "/home", "/root/.ssh"]);
