3286:/**
3287: * Perform a real lift-and-shift migration. Throws only on a FATAL setup error
3288: * (validation / target connect); every migration sub-step is best-effort and
3289: * records its outcome in the returned summary instead of aborting the run.
3290: */
3291:export async function runRealMigration(input: RealMigrationInput): Promise<RealMigrationSummary> {
3292:  const { migration, target, items, report } = input;
3293:  assert(target, "target server row not found");
3294:
3295:  // ---- 1. Validate EVERY non-secret input up front (fail closed) ----------
3296:  const host = migration.sourceHost;
3297:  const port = migration.sourcePort;
3298:  const user = migration.sourceUser;
