2463:  const { host, unit, unitFile, existsOnSource, copyFromSource, say } = opts;
2464:  const repairs: string[] = [];
2465:  const blockers: PendingItem[] = [];
2466:  if (!SVCNAME_RE.test(unit) || !validPath(unitFile)) return { ok: true, repairs, blockers };
2467:
2468:  const refs = parseUnitExecPaths(await host.readUnitFile(unitFile));
2469:  for (const ref of refs) {
2470:    if (await host.isExecutable(ref.path)) continue;
2471:
2472:    // It exists but is not executable — a real 203/EXEC cause too. Reported, not
2473:    // silently chmod-ed: changing the mode of the customer's own file is their
2474:    // call, and the command to do it is one line.
2475:    if (await host.exists(ref.path)) {
2476:      blockers.push({
2477:        domain: `${unit}.service`,
2478:        why: `its ${ref.directive} runs ${ref.path}, which exists on this server but is not executable — systemd will fail it with 203/EXEC`,
2479:        fix: `chmod +x ${ref.path} && systemctl restart ${unit}`,
2480:      });
2481:      continue;
2482:    }
2483:
2484:    // 1. The SAME program under a different prefix. This is the common case:
2485:    //    /usr/local/bin/node (hand-installed on the source) vs /usr/bin/node
2486:    //    (apt, on the target). A symlink makes the copied unit correct without
2487:    //    editing the customer's unit file.
2488:    const base = ref.path.slice(ref.path.lastIndexOf("/") + 1);
2489:    const dir = parentDir(ref.path);
2490:    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(base) && validPath(dir)) {
2491:      const found = await host.whichSameName(base);
2492:      if (found && found !== ref.path && validPath(found) && (await host.isExecutable(found))) {
2493:        if (await host.symlink({ target: found, linkPath: ref.path, dir })) {
2494:          repairs.push(`${unit}: ${ref.directive} wanted ${ref.path}, which is not on this server — linked it to ${found}`);
2495:          await say(`  ${unit}: ${ref.path} does not exist here, so it was linked to ${found} (the same program, installed in a different place).`);
2496:          continue;
2497:        }
2498:      }
2499:    }
2500:
2501:    // 2. Not present under any name — bring the actual file across.
2502:    if (await existsOnSource(ref.path)) {
2503:      if (await copyFromSource(ref.path)) {
2504:        repairs.push(`${unit}: copied ${ref.path} from the old server so ${ref.directive} can run`);
2505:        await say(`  ${unit}: copied ${ref.path} across from the old server.`);
2506:        continue;
2507:      }
2508:    }
2509:
2510:    // 3. Refuse to guess. A unit that cannot exec is worth one loud line.
2511:    blockers.push({
2512:      domain: `${unit}.service`,
2513:      why:
2514:        `its ${ref.directive} runs ${ref.path}, which does not exist on this server and is not installed anywhere else here ` +
2515:        `(systemd fails this as 203/EXEC and restarts the service forever)`,
2516:      fix:
2517:        `install the program that provides ${base} on this server, then either symlink it — ln -s "$(command -v ${base})" ${ref.path} — ` +
2518:        `or edit ${unitFile} to the real path, and run: systemctl daemon-reload && systemctl restart ${unit}`,
2519:    });
