2649:  conn: Client,
2650:  chosen: "nginx" | "apache",
2651:  say: (line: string) => Promise<void>
2652:): Promise<string[]> {
2653:  const keep = chosen === "apache" ? ["apache2", "httpd"] : ["nginx"];
2654:  const stood: string[] = [];
2655:  for (const svc of HOST_WEB_SERVERS) {
2656:    if (keep.includes(svc)) continue;
2657:    // Only touch units this machine actually has, so the log stays truthful.
2658:    const known = await shOk(conn, `systemctl list-unit-files ${svc}.service --no-legend 2>/dev/null | grep -q ${svc}`);
2659:    if (!known) continue;
2660:    const wasEnabled = clean((await sh(conn, `systemctl is-enabled ${svc} 2>/dev/null`)).stdout, 32);
2661:    const wasActive = clean((await sh(conn, `systemctl is-active ${svc} 2>/dev/null`)).stdout, 32);
2662:    if (wasEnabled === "masked") continue;
2663:    await sh(conn, `systemctl disable --now ${svc} >/dev/null 2>&1; systemctl mask ${svc} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
2664:    if (clean((await sh(conn, `systemctl is-enabled ${svc} 2>/dev/null`)).stdout, 32) === "masked") {
2665:      stood.push(svc);
2666:      await say(
2667:        `  Disabled ${svc} on this server (it was ${wasEnabled || "installed"}${wasActive === "active" ? ", running" : ""}) — ` +
2668:          `${chosen === "apache" ? "Apache" : "nginx"} owns ports 80/443 here and two web servers cannot share them. To bring it back: systemctl unmask ${svc}.`
2669:      );
2670:    }
2671:  }
