1390:/**
1391: * Make one image exist on the TARGET.
1392: *
1393: *   already present → nothing (a re-run must not re-transfer gigabytes)
1394: *   public registry → `docker pull` (fast, and costs no source bandwidth)
1395: *   otherwise       → `docker save | gzip` on the source, streamed straight
1396: *                     through the SSH channel into `gunzip | docker load`
1397: *
1398: * The locally-built case is the one that silently broke a real migration: the
1399: * engine copied files and named volumes but never the IMAGE, so standalone
1400: * containers could never start. A pull that fails also falls back to save/load,
1401: * so a private registry the new box cannot authenticate to still works.
1402: *
1403: * `ref` is validated by validImageRef before it reaches any command; success is
1404: * confirmed with `docker image inspect` rather than trusting an exit code
1405: * through a pipeline.
1406: */
1407:async function ensureImage(
1408:  conn: Client,
1409:  ref: string,
1410:  local: boolean,
1411:  onSource: (cmd: string) => string,
1412:  priv: string,
1413:  say: (line: string) => Promise<void>
1414:): Promise<{ status: "present" | "pulled" | "loaded" | "failed"; detail: string }> {
1415:  if (!validImageRef(ref)) return { status: "failed", detail: "image reference failed validation" };
1416:
1417:  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1418:    return { status: "present", detail: "already on the new server" };
1419:  }
1420:
1421:  if (!local) {
1422:    // A multi-gigabyte pull is one of the three steps that can sit silent for
1423:    // minutes, so it narrates itself (see withHeartbeat).
1424:    const pull = await withHeartbeat(`downloading the container image ${ref}`, say, () =>
1425:      sh(conn, `docker pull ${ref} 2>&1`, IMAGE_TIMEOUT_MS)
1426:    );
1427:    if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1428:      return { status: "pulled", detail: "pulled from its registry" };
1429:    }
1430:    const why = tailOf(pull, 1, 120);
1431:    await say(`  ${ref}: pull failed (${why || "unavailable"}) — transferring it from the old server instead.`);
1432:  }
1433:
1434:  // `docker save | gzip -1` on the source → `gunzip | docker load` on the target,
1435:  // through the SSH channel we already hold. gzip -1 because these links are
1436:  // usually faster than the CPU and the layers are mostly already compressed.
1437:  const stream = `${onSource(`${priv}docker save ${ref} | gzip -1`)} | gunzip -c | docker load 2>&1`;
1438:  const r = await withHeartbeat(`transferring the container image ${ref} from the old server`, say, () =>
1439:    sh(conn, stream, IMAGE_TIMEOUT_MS)
1440:  );
1441:  if (await shOk(conn, `docker image inspect ${ref} >/dev/null 2>&1`)) {
1442:    return { status: "loaded", detail: "transferred from the old server (docker save/load)" };
1443:  }
1444:  const why = tailOf(r, 2, 180);
1445:  return {
1446:    status: "failed",
1447:    detail: isEnospc(why)
1448:      ? "ran out of disk while loading the image"
1449:      : `could not pull or transfer the image${why ? `: ${why}` : ""}`,
1450:  };
1451:}
